SELECT CASE WHEN stock_qty >= 359 THEN 'high' WHEN stock_qty >= 69 THEN 'mid' ELSE 'low' END stock_qty_bucket, MAX(price) max_price, SUM(CASE WHEN category = 'Sports' THEN 1 ELSE 0 END) sports_count, SUM(CASE WHEN brand = 'Umbrella' THEN stock_qty ELSE 0 END) umbrella_stock_qty FROM products WHERE stock_qty >= 217 GROUP BY stock_qty_bucket HAVING umbrella_stock_qty > 62 ORDER BY umbrella_stock_qty DESC, stock_qty_bucket LIMIT 5
